import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Absent for accounts that only ever signed in via an OAuth provider (e.g. Google).
  passwordHash?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function findUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

/**
 * Creates a new email+password account. Throws if the email is already taken.
 */
export async function createUser(input: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (await findUserByEmail(email)) {
    throw new Error("An account with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(input.password, 10);
  const user: User = {
    id: String(nextId++),
    email,
    name: input.name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return user;
}

/**
 * Verifies email+password credentials. Returns the user on success, or
 * undefined if the email is unknown, has no password (OAuth-only), or the
 * password doesn't match.
 */
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const user = await findUserByEmail(email);
  if (!user?.passwordHash) return undefined;
  const ok = await bcrypt.compare(password, user.passwordHash);
  return ok ? user : undefined;
}

/**
 * Finds or creates the user record backing an OAuth (Google) sign-in.
 * OAuth accounts have no passwordHash and can't sign in via credentials.
 */
export async function findOrCreateOAuthUser(input: {
  email: string;
  name?: string | null;
}): Promise<User> {
  const existing = await findUserByEmail(input.email);
  if (existing) return existing;

  const email = input.email.trim().toLowerCase();
  const user: User = {
    id: String(nextId++),
    email,
    name: input.name?.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  return user;
}

