import { chromium } from "playwright";

const BASE = "http://localhost:3900";
const SCRATCH = process.env.SCRATCH;
const email = `test-${Date.now()}@example.com`;
const password = "correcthorsebattery";
const name = "Test User";

const results = [];
const shot = (page, label) => page.screenshot({ path: `${SCRATCH}/${label}.png` });

const browser = await chromium.launch();
const page = await browser.newPage();

try {
  // 1) sign up
  await page.goto(`${BASE}/signup`);
  await page.fill('input[name="name"]', name);
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button[type="submit"]:has-text("Sign up")');
  await page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 });
  const dashText1 = await page.textContent("body");
  const step1 =
    dashText1.includes(name) && dashText1.includes(email);
  results.push([
    "1) signup -> dashboard shows name/email",
    step1,
    dashText1.match(/Signed in as.*?\)/)?.[0],
  ]);
  await shot(page, "01-dashboard-after-signup");

  // 2) sign out
  await page.click('button:has-text("Sign out")');
  await page.waitForURL(`${BASE}/`, { timeout: 10000 });
  const bodyAfterSignout = await page.textContent("body");
  const step2 =
    bodyAfterSignout.includes("Sign in") && bodyAfterSignout.includes("Sign up");
  results.push(["2) sign out -> home, header shows Sign in/Sign up", step2]);
  await shot(page, "02-home-after-signout");

  // 3) direct dashboard visit while signed out
  await page.goto(`${BASE}/dashboard`);
  await page.waitForURL(/\/signin/, { timeout: 10000 });
  const step3 = page.url().includes("/signin");
  results.push(["3) /dashboard while signed out -> redirected to /signin", step3, page.url()]);
  await shot(page, "03-redirected-to-signin");

  // 4) sign back in
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button[type="submit"]:has-text("Sign in")');
  await page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 });
  const dashText2 = await page.textContent("body");
  const step4 = dashText2.includes(name) && dashText2.includes(email);
  results.push(["4) signin -> dashboard again", step4]);
  await shot(page, "04-dashboard-after-signin");
} catch (err) {
  results.push(["ERROR", false, String(err)]);
  await shot(page, "99-error");
} finally {
  await browser.close();
}

for (const [label, ok, extra] of results) {
  console.log(`${ok ? "PASS" : "FAIL"} — ${label}${extra ? " — " + extra : ""}`);
}

